# The frozen arithmetic is generated by pinned original R, never rsdeseq2.
.row_reference_values <- function(values) vapply(values,function(value)
  readBin(as.raw(strtoi(substring(value,seq(1,15,2),seq(2,16,2)),16L)),"double",n=1,size=8,endian="big"),numeric(1))
.row_reference_bits <- function(values) lapply(unname(values),function(value)writeBin(value,raw(),size=8,endian="big"))

test_that("borrowed row preparation and offset products match independent R bits", {
  r <- jsonlite::fromJSON(test_path("data","row_preparation_r462.json"),simplifyVector=FALSE)
  expect_length(r$offsets,12L);expect_length(r$rows,6L)
  for(case in r$offsets) {
    ct <- matrix(1,case$genes,case$samples,dimnames=list(paste0("g",seq_len(case$genes)),paste0("s",seq_len(case$samples))))
    sf <- if(is.null(case$size_factors))NULL else .row_reference_values(case$size_factors)
    nf <- if(is.null(case$factors))NULL else matrix(.row_reference_values(case$factors),case$genes,case$samples,byrow=TRUE)
    run <- function().Call("rsdeseq2_offset_factors",ct,sf,nf,.row_reference_values(case$offsets),PACKAGE="rsdeseq2")
    if(is.null(case$expected)) expect_error(run(),"offset|normalization factor",info=case$name) else {
      actual <- run()
      expect_identical(.row_reference_bits(as.vector(t(actual))),.row_reference_bits(.row_reference_values(case$expected)),info=case$name)
      expect_identical(dimnames(actual),dimnames(ct),info=case$name)
    }
  }
  for(case in r$rows) {
    ct <- matrix(as.double(unlist(case$counts)),case$genes,case$samples,byrow=TRUE)
    expect_identical(.Call("rsdeseq2_validate_counts",ct,PACKAGE="rsdeseq2"),ct,info=case$name)
    run <- function().Call("rsdeseq2_normal_shrinkage_rows",ct,
      .row_reference_values(case$dispersions),.row_reference_values(case$fitted),
      if(is.null(case$excluded))NULL else as.logical(unlist(case$excluded)),PACKAGE="rsdeseq2")
    if(is.null(case$expected))expect_error(run(),"normal lfcShrink",info=case$name)
    else expect_identical(run(),as.integer(unlist(case$expected))+1L,info=case$name)
  }
  for(bad in list(NA_real_,Inf,-1,.5,4294967296)) {
    ct <- matrix(c(0,bad),1,2)
    expect_error(rsdeseq2:::.rsdeseq2_validate_counts(ct),"valid u32 count")
  }
  ct <- matrix(c(0L,1L,2L,3L),2,2,dimnames=list(c("zero","nonzero"),c("a","b")))
  expected <- ct;storage.mode(expected) <- "double"
  expect_identical(rsdeseq2:::.rsdeseq2_validate_counts(ct),expected)
})

test_that("normal shrinkage preserves fitted weight exclusions and supplied result row order", {
  ct <- .rsdeseq2_test_counts()
  cd <- data.frame(condition=factor(rep(c("A","B"),each=4)),row.names=colnames(ct))
  dds <- DESeq2::DESeqDataSetFromMatrix(ct,cd,~condition)
  weights <- matrix(1,nrow(ct),ncol(ct),dimnames=dimnames(ct));weights[3,5:8] <- 0
  SummarizedExperiment::assay(dds,"weights") <- weights
  reference <- suppressWarnings(DESeq2::DESeq(dds,fitType="mean",minReplicatesForReplace=Inf,quiet=TRUE))
  fitted <- DESeq(dds,fitType="mean",minReplicatesForReplace=Inf)
  expect_true(S4Vectors::mcols(reference)$allZero[3]);expect_true(any(ct[3,]>0))
  scenarios <- list(coefficient=list(coef=2L),contrast=list(contrast=c("condition","B","A")),
    threshold=list(coef=2L,lfcThreshold=.5))
  for(name in names(scenarios)) {
    options <- c(list(type="normal"),scenarios[[name]])
    actual <- suppressMessages(do.call(rsdeseq2::lfcShrink,c(list(dds=fitted),options)))
    expected <- suppressMessages(do.call(DESeq2::lfcShrink,c(list(dds=reference,quiet=TRUE),options)))
    fields <- if(name=="threshold")c("log2FoldChange","lfcSE","stat","pvalue","padj")else c("log2FoldChange","lfcSE")
    for(field in fields) {
      expect_identical(is.na(actual[[field]]),is.na(expected[[field]]),info=paste(name,field))
      expect_equal(as.numeric(actual[[field]]),as.numeric(expected[[field]]),tolerance=1e-5,info=paste(name,field))
    }
    expect_true(is.na(actual$log2FoldChange[3]),info=name)
  }
  selected <- c(9,3,5,1,8,12)
  supplied <- as.data.frame(results(fitted))[selected,,drop=FALSE]
  actual <- suppressMessages(lfcShrink(fitted,coef=2,type="normal",res=supplied))
  expected <- suppressMessages(DESeq2::lfcShrink(reference[selected,],coef=2,type="normal",quiet=TRUE))
  expect_identical(rownames(actual),rownames(ct)[selected])
  expect_identical(as.numeric(actual$pvalue),supplied$pvalue)
  expect_identical(as.numeric(actual$padj),supplied$padj)
  expect_equal(as.numeric(actual$log2FoldChange),as.numeric(expected$log2FoldChange),tolerance=1e-5)
  expect_equal(as.numeric(actual$lfcSE),as.numeric(expected$lfcSE),tolerance=1e-5)
})
